{
  "headline": "FDA's records trace our supply to a plant classified OAI 510 days before the posting",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA first posted the hydromorphone hydrochloride injection shortage on 2017-10-31 and it remains Current as of 2026-10-21.",
      "cites": ["E38", "E33", "E34", "E35", "E36"]
    },
    {
      "text": "The shortage posting lists Fresenius Kabi USA LLC, Hikma Pharmaceuticals USA Inc., Hospira Inc. (a Pfizer Company), and Teva Pharmaceuticals USA Inc. as affected companies.",
      "cites": ["E33", "E34", "E35", "E36"]
    },
    {
      "text": "FDA inspection 976095 at Hospira Inc. (FEI 1925262) ended 2016-06-08 and was classified OAI, 510 days before the shortage posting.",
      "cites": ["D8", "E24"]
    },
    {
      "text": "A Warning Letter was issued to Hospira Inc. (FEI 1925262) on 2017-02-14, 259 days before the posting.",
      "cites": ["D9", "E29"]
    },
    {
      "text": "FDA inspection 1031233 at Hospira Inc. (FEI 1925262) ended 2017-10-27 and was classified VAI, 4 days before the posting.",
      "cites": ["D10", "E25"]
    },
    {
      "text": "Corvale East has 2.8 days of 2 mg/mL 20 mL vials on hand while Corvale General has 21.3 days.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule‑ranked best option is to transfer 139 vials of 2 mg/mL 20 mL from Corvale General to Corvale East, which would give Corvale East 9 days of supply.",
      "cites": ["D15"]
    }
  ]
}
